9	
10	// seedUsage 直接向台账写入带不同时区偏移的申请记录并保存，
11	// 模拟同一台机器在不同系统时区下先后留下的历史。
12	func seedUsage(t *testing.T, l *Ledger, recs ...UsageRecord) {
13		t.Helper()
14		l.data.Usage = append(l.data.Usage, recs...)
15		if err := l.save(); err != nil {
16			t.Fatalf("保存测试记录失败: %v", err)
17		}
18	}
19	
20	func usageKeys(recs []UsageRecord) [][2]string {
21		got := make([][2]string, len(recs))
22		for i, r := range recs {
23			got[i] = [2]string{r.InstrumentID, r.RequestedAt}
24		}
25		return got
26	}
27	
28	// TestUsageRecordsOrderByActualInstantAcrossOffsets 验证不同时区偏移下按申请
29	// 发生的实际时刻排序：2026-10-05T10:30:00+09:00（01:30Z）实际早于
30	// 2026-10-05T10:00:00+08:00（02:00Z），虽然后者文字上的小时、分钟更小。
31	// 获准与被拒绝的申请一起按时刻排序，结果不参与排序。
32	func TestUsageRecordsOrderByActualInstantAcrossOffsets(t *testing.T) {
33		clock := &fakeClock{t: mustDate(t, "2026-10-05")}
34		path := filepath.Join(t.TempDir(), "ledger.json")
35		l, err := openAt(path, clock.now)
36		if err != nil {
37			t.Fatalf("open: %v", err)
38		}
39		// 按错误的字符串顺序写入（实际较晚的先入库），排序不能沿用入库或文字顺序。
40		seedUsage(t, l,
41			UsageRecord{InstrumentID: "M-2", RequestedAt: "2026-10-05T10:00:00+08:00",
42				Allowed: false, Reasons: []string{"较晚的被拒绝申请"}},
43			UsageRecord{InstrumentID: "M-1", RequestedAt: "2026-10-05T10:30:00+09:00",
44				Allowed: true, Reasons: []string{}},
45		)
46	
47		recs := l.UsageRecords()
48		want := [][2]string{
49			{"M-1", "2026-10-05T10:30:00+09:00"},
50			{"M-2", "2026-10-05T10:00:00+08:00"},
51		}
52		if got := usageKeys(recs); !reflect.DeepEqual(got, want) {
53			t.Fatalf("应按实际时刻从早到晚排列，得到 %v，期望 %v", got, want)
54		}
55		// 原文字及偏移、申请结果与拒绝原因保持保存时的内容。
56		if !recs[0].Allowed || len(recs[0].Reasons) != 0 {
57			t.Fatalf("获准记录的结果或原因被改动：%+v", recs[0])
58		}
59		if recs[1].Allowed || !sameReasons(recs[1].Reasons, []string{"较晚的被拒绝申请"}) {
60			t.Fatalf("被拒绝记录的结果或冻结原因被改动：%+v", recs[1])
61		}
62	
63		// 查询只重排返回的独立副本，不回写台账：台账内部仍按保存顺序保存。
64		if got := usageKeys(l.data.Usage); !reflect.DeepEqual(got, [][2]string{
65			{"M-2", "2026-10-05T10:00:00+08:00"},
66			{"M-1", "2026-10-05T10:30:00+09:00"},
67		}) {
68			t.Fatalf("查询不应重排台账内存储：%v", got)
69		}
70		// 重新打开同一文件后，历史仍按各自保存的时间确定先后。
71		reopened, err := openAt(path, clock.now)
72		if err != nil {
73			t.Fatalf("reopen: %v", err)
74		}
75		if got := usageKeys(reopened.UsageRecords()); !reflect.DeepEqual(got, want) {
76			t.Fatalf("重开后排序应仍按实际时刻：%v", got)
77		}
78	}
79	
80	// TestUsageRecordsOrderAcrossMidnightOffsets 验证跨日记录同样按实际时刻：
81	// 2026-10-06T00:10:00+09:00（15:10Z）早于 2026-10-05T23:30:00+08:00（15:30Z）。
82	func TestUsageRecordsOrderAcrossMidnightOffsets(t *testing.T) {
83		clock := &fakeClock{t: mustDate(t, "2026-10-05")}
84		l := newTestLedger(t, clock)
85		seedUsage(t, l,
86			UsageRecord{InstrumentID: "M-1", RequestedAt: "2026-10-05T23:30:00+08:00",
87				Reasons: []string{}},
88			UsageRecord{InstrumentID: "M-2", RequestedAt: "2026-10-06T00:10:00+09:00",
89				Reasons: []string{}},
90		)
91		recs := l.UsageRecords()
92		want := [][2]string{
93			{"M-2", "2026-10-06T00:10:00+09:00"},
94			{"M-1", "2026-10-05T23:30:00+08:00"},
95		}
96		if got := usageKeys(recs); !reflect.DeepEqual(got, want) {
97			t.Fatalf("跨日记录应按实际时刻排列，得到 %v，期望 %v", got, want)
98		}
99	}
100	
101	// TestUsageRecordsSameInstantTieBreak 验证实际时刻相同时的次序规则：
102	// Z 与显式零偏移表示同一时刻时不产生额外优先级；先按器具编号升序，
103	// 同一器具同一时刻的多次申请保留台账原有次序且全部保留、不合并。
104	func TestUsageRecordsSameInstantTieBreak(t *testing.T) {
105		clock := &fakeClock{t: mustDate(t, "2026-10-05")}
106		l := newTestLedger(t, clock)
107		seedUsage(t, l,
108			// 同一时刻的两种文字形式、不同器具：按编号升序，与文字形式无关。
109			UsageRecord{InstrumentID: "M-2", RequestedAt: "2026-10-05T10:00:00Z", Reasons: []string{}},
110			UsageRecord{InstrumentID: "M-1", RequestedAt: "2026-10-05T10:00:00+00:00", Reasons: []string{}},
111			// 同一器具同一时刻的三次申请（含 Z 与零偏移、+08:00 混用）：保留入库次序。
112			UsageRecord{InstrumentID: "M-1", RequestedAt: "2026-10-05T10:00:00Z",
113				Allowed: false, Reasons: []string{"第一次"}},
114			UsageRecord{InstrumentID: "M-1", RequestedAt: "2026-10-05T10:00:00+00:00",
115				Allowed: true, Reasons: []string{}},
116			UsageRecord{InstrumentID: "M-1", RequestedAt: "2026-10-05T18:00:00+08:00",
117				Allowed: false, Reasons: []string{"第三次"}},
118		)
119		recs := l.UsageRecords()
120		want := [][2]string{
121			{"M-1", "2026-10-05T10:00:00+00:00"},
122			{"M-1", "2026-10-05T10:00:00Z"},
123			{"M-1", "2026-10-05T10:00:00+00:00"},
124			{"M-1", "2026-10-05T18:00:00+08:00"},
125			{"M-2", "2026-10-05T10:00:00Z"},
126		}
127		if got := usageKeys(recs); !reflect.DeepEqual(got, want) {
128			t.Fatalf("同一时刻应按编号升序、同编号保留原次序，得到 %v，期望 %v", got, want)
129		}
130		if len(recs) != 5 {
131			t.Fatalf("同一器具同一时刻的多次申请必须全部保留、不得合并，得到 %d 条", len(recs))
132		}
133		if !sameReasons(recs[1].Reasons, []string{"第一次"}) ||
134			!recs[2].Allowed ||
135			!sameReasons(recs[3].Reasons, []string{"第三次"}) {
136			t.Fatalf("同刻多次申请的结果与冻结原因次序被打乱：%+v", recs)
137		}
138	
139		// 同刻同编号记录若以相反顺序入库，稳定排序应保留相反的原次序，
140		// 时间的文字形式不产生额外优先级。
141		l2 := newTestLedger(t, clock)
142		seedUsage(t, l2,
143			UsageRecord{InstrumentID: "M-1", RequestedAt: "2026-10-05T10:00:00+00:00",
144				Reasons: []string{"先入库"}},
145			UsageRecord{InstrumentID: "M-1", RequestedAt: "2026-10-05T10:00:00Z",
146				Reasons: []string{"后入库"}},
147		)
148		got2 := l2.UsageRecords()
149		if !sameReasons(got2[0].Reasons, []string{"先入库"}) ||
150			!sameReasons(got2[1].Reasons, []string{"后入库"}) {
151			t.Fatalf("同刻同编号应保留台账原次序，文字形式不得加优先级：%+v", got2)
152		}
153	}
154	
155	// TestUsageRecordsEmptyAndSingle 验证没有记录时返回空结果，
156	// 只有一条时原样返回（文字与偏移不变）。
157	func TestUsageRecordsEmptyAndSingle(t *testing.T) {
158		clock := &fakeClock{t: mustDate(t, "2026-10-05")}
159		l := newTestLedger(t, clock)
160		if recs := l.UsageRecords(); len(recs) != 0 {
161			t.Fatalf("没有申请记录时应返回空结果，得到 %+v", recs)
162		}
163		seedUsage(t, l, UsageRecord{InstrumentID: "M-9", RequestedAt: "2026-10-05T23:59:00-03:00",
164			Allowed: true, Reasons: []string{}})
165		recs := l.UsageRecords()
166		if len(recs) != 1 ||
167			recs[0].InstrumentID != "M-9" ||
168			recs[0].RequestedAt != "2026-10-05T23:59:00-03:00" {
169			t.Fatalf("只有一条记录时应原样返回：%+v", recs)
170		}
171	}
172	
173	// TestUsageRecordsOrderingUnaffectedByCurrentZone 验证查询当天的系统时区
174	// 变化不能改变历史顺序：同一份文件分别用不同时区的“现在”打开，先后一致。
175	func TestUsageRecordsOrderingUnaffectedByCurrentZone(t *testing.T) {
176		path := filepath.Join(t.TempDir(), "ledger.json")
177		clock := &fakeClock{t: mustDate(t, "2026-10-05")}
178		l, err := openAt(path, clock.now)
179		if err != nil {
180			t.Fatalf("open: %v", err)
181		}
182		seedUsage(t, l,
183			UsageRecord{InstrumentID: "M-1", RequestedAt: "2026-10-05T10:00:00+08:00", Reasons: []string{}},
184			UsageRecord{InstrumentID: "M-2", RequestedAt: "2026-10-05T10:30:00+09:00", Reasons: []string{}},
185		)
186		want := [][2]string{
187			{"M-2", "2026-10-05T10:30:00+09:00"},
188			{"M-1", "2026-10-05T10:00:00+08:00"},
189		}
190		zones := []struct {
191			name string
192			loc  *time.Location
193		}{
194			{"UTC", time.UTC},
195			{"UTC+05:30", time.FixedZone("UTC+05:30", 5*3600+1800)},
196			{"UTC-07:00", time.FixedZone("UTC-07:00", -7*3600)},
197		}
198		for _, z := range zones {
199			loc := z.loc
200			opened, err := openAt(path, func() time.Time { return clock.t.In(loc) })
201			if err != nil {
202				t.Fatalf("reopen in %s: %v", z.name, err)
203			}
204			if got := usageKeys(opened.UsageRecords()); !reflect.DeepEqual(got, want) {
205				t.Fatalf("在时区 %s 查询改变了历史顺序：%v", z.name, got)
206			}
207		}
208	}
