	)
	want := []string{"PL-EARLY", "PL-LATE"}
	zones := []struct {
		name string
		loc  *time.Location
	}{
		{"UTC", time.UTC},
		{"UTC+05:30", time.FixedZone("UTC+05:30", 5*3600+1800)},
		{"UTC-07:00", time.FixedZone("UTC-07:00", -7*3600)},
	}
	for _, z := range zones {
		loc := z.loc
		opened, err := openAt(path, func() time.Time { return clock.t.In(loc) })
