		if err != nil {
			t.Fatalf("Review in %s: %v", z.name, err)
		}
		if got := planNumbers(review.Plans); !reflect.DeepEqual(got, want) {
			t.Fatalf("在时区 %s 核对改变了历史顺序：%v", z.name, got)
		}
	}
}

